def texte_complet(nom_fichier, separateur):
    f = open(nom_fichier, 'r', encoding='utf-8')
    lignes = f.readlines()
    f.close()
    res = ''
    for ligne in lignes:
        if ligne.endswith('\n'):
            res = res + ligne[:-1] + separateur
        else:
            res = res + ligne
    return res
